import random

def calculate_energy(seq):
    n = len(seq)
    energy = 0
    for k in range(1, n):
        c_k = sum(seq[i] * seq[i+k] for i in range(n-k))
        energy += c_k**2
    return energy

def hill_climbing(n, max_iter=1000000):
    seq = [random.choice([-1, 1]) for _ in range(n)]
    current_energy = calculate_energy(seq)

    for _ in range(max_iter):
        if current_energy <= 84:
            return seq

        # Flip a random bit
        idx = random.randint(0, n-1)
        seq[idx] *= -1
        new_energy = calculate_energy(seq)

        if new_energy <= current_energy:
            current_energy = new_energy
        else:
            # Revert
            seq[idx] *= -1

    return None

# Try multiple restarts
for _ in range(100):
    result = hill_climbing(29)
    if result:
        print(result)
        break
else:
    print("No solution found")

